    let embedUrl = 'https://partner.transistor.fm/ghost/embed/{uuid}';
    if (options.siteUuid) {
        embedUrl += `?ctx=${options.siteUuid}`;
    }

    // Inline script that detects the background color of the embed's parent element
    // and forwards it to the iframe via a query parameter before loading the real src.
    // The iframe uses data-src so it only loads once the background has been resolved.
    const script = `
        function setSrcBackgroundFromParent(iframe) {
            var src = iframe.getAttribute('data-src');
            if (!src) {
                return;
            }
            var parent = iframe.parentElement;
            var background = '';
            while (parent) {
                var computed = window.getComputedStyle(parent).backgroundColor;
                if (computed && computed !== 'transparent' && computed !== 'rgba(0, 0, 0, 0)') {
                    background = computed;
                    break;
                }
                parent = parent.parentElement;
            }
            if (background) {
                var separator = src.indexOf('?') === -1 ? '?' : '&';
                src = src + separator + 'background=' + encodeURIComponent(background);
            }
            iframe.setAttribute('src', src);
        }
        var transistorEmbeds = document.querySelectorAll('iframe[data-kg-transistor-embed]');
        for (var i = 0; i < transistorEmbeds.length; i += 1) {
            setSrcBackgroundFromParent(transistorEmbeds[i]);
